  "Each band runs from its own number up to the next one's. A band with no tags writes nothing.": "各帯は自分の数値から次の数値までを覆います。タグのない帯は何も書き込みません。",
  "A picture the ranking placed is read at its own standing, never at the fit's guess about it.": "ランキングが順位を付けた画像は、推定値ではなくその順位そのもので読まれます。",
