  "carriers of this meta tag are updated.": "このメタタグの担い手が更新されます。",
  "Merge meta tags?": "メタタグを統合しますか？",
  "Merge meta tags": "メタタグを統合",
  "labels onto it: every link, caption and tag group carrying the old name carries the new one instead (a carrier holding both keeps one).": "のラベルがそこに移ります。古い名前を持つすべてのリンク、キャプション、タググループは代わりに新しい名前を持ちます（両方を持っていた担い手はひとつだけ残します）。",
  "A meta tag has no aliases, so the old name simply goes.": "メタタグにエイリアスはないため、古い名前は単に消えます。",
  "This is recorded, so it can be undone from the History tab.": "この操作は記録されるため、履歴タブから元に戻せます。",
  "No meta tag has this name yet — it is created, and everything is folded into it.": "この名前のメタタグはまだありません — 新しく作成され、すべてがそこに畳み込まれます。",
  "One of the selected meta tags, or any other: everything is folded into it.": "選択したメタタグのひとつでも他のものでも構いません。すべてがそこに畳み込まれます。",
  "Every link, caption and tag group carrying one of these names carries the target instead; a carrier that held two of them keeps one. Each rename is recorded, so this can be undone.": "これらの名前を持つすべてのリンク、キャプション、タググループは代わりに統合先を持ちます。2 つ持っていた担い手はひとつだけ残します。各リネームは記録されるため、元に戻せます。",
