  "Run the queue — jobs start in this order, one per GPU, until it is empty.": "キューを実行 — ジョブはこの順で、GPU ごとに 1 つずつ、空になるまで開始されます。",
  "Pause — checkpoints and stops the running job; the queue stops with it.": "一時停止 — 実行中のジョブをチェックポイントして停止し、キューも一緒に止まります。",
  "Drag to change the run order — or out of Up next to put the job on hold": "ドラッグで実行順を変更 — 「次に実行」の外へ出すと保留になります",
  "The queue is empty. Drag jobs here (or use their queue button) — they run in this order once the queue is started.": "キューは空です。ジョブをここにドラッグ（またはキューボタンを使用）してください — キューを開始すると、この順で実行されます。",
  "Milestones that stay for good, spread across the whole run: with a cadence of 200 steps and one in 5, the snapshots at 1000, 2000, 3000 … are never deleted. This is what lets you compare an early style against a late one after the run is over, and it combines with the window above — a snapshot is kept when either rule wants it. 0 turns it off.": "実行全体にわたって恒久的に残るマイルストーンです。間隔 200 ステップで 5 回に 1 回なら、1000、2000、3000 … のスナップショットは削除されません。実行後に序盤のスタイルと終盤を比較できるのはこれのおかげで、上のウィンドウとも組み合わさります — どちらかのルールが望めばスナップショットは保持されます。0 でオフになります。",
  "Sample": "サンプル",
  "Save this pause state as a checkpoint — otherwise it is replaced the next time the job pauses": "この一時停止状態をチェックポイントとして保存 — 保存しないと、次にジョブが一時停止したときに置き換えられます",
