  "The long form — what it covers, when to reach for it, what it is not. Shown behind the ? beside the name.": "長い方 — 何を含むか、どんなときに使うか、何ではないか。名前の横の ? の奥に表示されます。",
  "What it is, in a line — “the hotel bar”…": "それが何かを一行で —「ホテルのバー」…",
