  "Waiting for the GPU…": "GPU を待っています…",
  "Seed": "シード",
  "How strongly the prompt is enforced. Anything above 1 makes the model run TWICE per sampler step — once with the prompt and once without — so it costs about double the time (measured here on SDXL at 1024², 20 steps: 53 s at 6 against 24 s at 1). At 1 or below that second pass is skipped, but these models are trained to lean on guidance and the picture changes completely without it — so treat this as a quality dial that happens to cost time, not as a speed setting.": "プロンプトをどれだけ強く効かせるかです。1 を超えるとモデルはサンプラーステップごとに 2 回 — プロンプトありとなしで — 実行され、時間は約 2 倍かかります（当環境の SDXL、1024²、20 ステップでの実測: 6 で 53 秒、1 で 24 秒）。1 以下ではその 2 回目のパスは省かれますが、これらのモデルはガイダンスに頼るよう学習されており、なしでは絵が完全に変わります — これは速度設定ではなく、時間のかかる品質ダイヤルとして扱ってください。",
  "Enable downloads": "ダウンロードを有効化",
  "queued": "待機中",
  "px": "px",
  "w/h": "幅/高",
  "The 1024 px release: Chroma1 Base given a high-resolution finetune, so it holds detail and composition at 1024 and is the one to train on unless you are working smaller.": "1024 px リリース — Chroma1 Base に高解像度ファインチューンを施したもので、1024 でディテールと構図を保ちます。より小さく作業するのでなければ、学習すべきはこちらです。",
  "The 512 px release HD was finetuned from. Trains faster and cheaper at 512, and is the better start if your images are small or you want the un-finetuned base to build on.": "HD の元になった 512 px リリースです。512 なら速く安く学習でき、画像が小さい場合や、素のベースの上に構築したい場合はこちらが良い出発点です。",
  "Hugging Face": "Hugging Face",
  "Local path": "ローカルパス",
  "Downloading…": "ダウンロード中…",
  "Downloaded": "ダウンロード済み",
  "Downloads are switched off": "ダウンロードはオフになっています",
  "Download": "ダウンロード",
  "Download this model": "このモデルをダウンロード",
