  "tag": "タグ",
  "Edit this subject — name, comment and date": "この被写体を編集 — 名前、コメント、日付",
  "Create": "作成",
  "Merge into an existing tag?": "既存のタグに統合しますか？",
  "That tag already exists. Merging folds this subject's tag into it: every picture carrying the old one carries the new one instead, along with what it implied and the groups that assigned it.": "そのタグはすでに存在します。統合すると、この被写体のタグはそこに畳み込まれます。古いタグを持つすべての画像は代わりに新しいタグを持ち、含意していたものや割り当てていたグループも一緒に移ります。",
  "It is also somebody's identity, so the two subjects become one.": "それは誰かのアイデンティティでもあるため、2 つの被写体はひとつになります。",
  "New subject": "新しい被写体",
  "Somebody or something a picture can be OF": "画像が写しうる誰か、または何か",
  "Edit subject": "被写体を編集",
  "Exists since": "存在開始",
  "1975, 7/1999, 14.3.1879": "1975、7/1999、14.3.1879",
  "a_tag_name": "a_tag_name",
  "Rename the tag along with the subject": "被写体と一緒にタグも改名する",
  "That date doesn't look like a date.": "日付のようには見えません。",
  "Merge subjects?": "被写体を統合しますか？",
  "Another subject already has this name and comment. Merging moves everything this one carries onto it: every picture it is in, what its tag implies, and (later) its faces.": "同じ名前とコメントの被写体がすでにあります。統合すると、こちらが持つすべて — 写っている画像、タグの含意、（後には）顔 — がそこに移ります。",
  "The old tag stays behind as an alias, so anything still using it finds the merged subject.": "古いタグはエイリアスとして残るため、それを使っているものは統合先の被写体にたどり着きます。",
  "No date on this item": "このアイテムに日付はありません",
  "Set a date": "日付を設定",
  "Change the date": "日付を変更",
  "It has no date": "日付はない",
  "year, date, or date and time": "年、日付、または日付と時刻",
  "from the file's EXIF data": "ファイルの EXIF データから",
  "from the event below": "下のイベントから",
  "How old they are in this item": "このアイテムでのその人の年齢",
  "Say who this is": "これが誰かを教える",
  "Subjects": "被写体",
  "Nothing": "なし",
  "Puts something in front of each group's tags, so a block reads “Alice: blonde hair, dress” instead of “blonde hair, dress”.\n\nThe group's NAME is right when your groups are named for what they show. The SUBJECTS it is about are usually better: a group called “front figure” is bookkeeping, while the subject on it is “Alice” — the word you would actually type at generation time.\n\nA group with no subjects gets no label at all under that choice, rather than quietly falling back to its name.": "各グループのタグの前に何かを置き、ブロックが「blonde hair, dress」ではなく「Alice: blonde hair, dress」と読めるようにします。\n\nグループの名前が正しいのは、グループが写っているものにちなんで名付けられている場合です。たいていはグループが指す被写体の方が良い選択です。「front figure」というグループ名は帳簿付けで、そこにある被写体は「Alice」 — 生成時に実際に入力する言葉です。\n\n被写体のないグループは、その選択では黙って名前にフォールバックせず、ラベルなしになります。",
  "Say who this group is about": "このグループが誰についてかを教える",
  "What to write in front of a block, as “label: tags”. Nothing by default — a group's name is often for the person tagging rather than for the model.": "ブロックの前に「ラベル: タグ」の形で何を書くかです。デフォルトはなし — グループ名はモデルではなく、タグ付けする人のためのものであることが多いからです。",
  "Named": "命名済み",
  "No tag": "タグなし",
  "A per-item tag group is usually about one thing in the picture — Alice's hair and dress, Bob's hat. Flattened into one comma list, the model is left to work out which adjective belongs to whom, and in a busy image it often gets it wrong.\n\nWith this on, the tags the random pick chose are laid out per group, in the order the pick produced, so shuffling still applies within a block. Tags in no group lead, because they describe the scene the groups sit inside. A tag that is in two groups is written under the first one — the same tag twice reads as emphasis and teaches nothing.": "アイテムごとのタググループは、たいてい絵の中のひとつのものについてです — アリスの髪とドレス、ボブの帽子。ひとつのカンマ列に平坦化すると、どの形容詞が誰のものかをモデルが自力で解くことになり、にぎやかな絵ではよく間違えます。\n\nオンにすると、ランダム選択が選んだタグがグループごとに、選択の生んだ順で並びます。シャッフルはブロック内では引き続き適用されます。どのグループにもないタグが先頭に来ます。それらはグループが収まるシーンを記述するからです。2 つのグループにあるタグは最初のグループの下に書かれます — 同じタグが 2 回あると強調と読まれ、何も教えないからです。",
  "The string between one group's block and the next. A newline is the default because it is what makes the blocks read as separate statements rather than one longer list.\n\nIf your prompts are consumed somewhere that cannot carry line breaks, a distinctive string such as “ | ” works too — just use the same convention when you write generation prompts.": "あるグループのブロックと次のブロックの間の文字列です。デフォルトは改行です。ブロックがひとつの長いリストではなく、別々の文として読めるのは改行のおかげだからです。\n\nプロンプトの行き先が改行を運べない場合は、「 | 」のような特徴的な文字列でも構いません — 生成プロンプトを書くときも同じ規約を使ってください。",
  "not a face": "顔ではない",
  "Fold the selected subjects into one": "選択した被写体をひとつに畳む",
  "Merge subjects": "被写体を統合",
  "Keep": "残す",
  "The one that survives. The others' faces, pictures and dates move onto it.": "生き残るものです。他の被写体の顔、画像、日付がそこに移ります。",
  "Keep each old tag as an alias, so anything still using it finds the merged subject": "古いタグをそれぞれエイリアスとして残し、使っているものが統合先の被写体にたどり着けるようにする",
  "{slug} already belongs to another tag. Pick another name.": "{slug} はすでに別のタグのものです。別の名前を選んでください。",
  "{slug} already belongs to another tag — saving offers to merge them.": "{slug} はすでに別のタグのものです — 保存すると統合を提案します。",
