  "A ranking places your pictures on an axis — quality, composition, art style — by quick side-by-side comparisons. Rate pairs with the keyboard and every picture gets a score tag (quality:0 … quality:9) that search and training can use, kept up to date automatically.": "ランキングは、素早い並べ替え比較によって画像をひとつの軸（品質・構図・画風など）の上に並べます。キーボードでペアを評価すると、各画像にスコアタグ（quality:0 … quality:9）が付き、検索や学習で使えます。自動で最新に保たれます。",
